import type { DrawInViewOptions } from './draw-in-view.motion.js';

export interface ScribbleHighlightProps extends DrawInViewOptions {
    /** Shape drawn around the default slot. @default 'underline' */
    variant?: 'underline' | 'circle';
}

/** Vue component refs expose the root DOM element, null when presence removes it. */
export interface KidaElement {
    element: HTMLElement | null;
}

@import './tokens.css';

[data-kida-scribble] {
  --kida-scribble-color: #e94f86;
  --kida-scribble-width: 0.14em;
  --kida-scribble-duration: 650ms;

  position: relative;
  display: inline-block;
  isolation: isolate;
}

[data-kida-scribble-content] {
  position: relative;
  z-index: 1;
}

[data-kida-scribble] svg {
  position: absolute;
  z-index: 0;
  left: -4%;
  width: 108%;
  overflow: visible;
  pointer-events: none;
}

[data-kida-scribble][data-variant="underline"] svg {
  top: 78%;
  height: 0.55em;
}

[data-kida-scribble][data-variant="circle"] svg {
  inset: -12% -7%;
  width: 114%;
  height: 124%;
}

[data-kida-scribble] path {
  fill: none;
  stroke: var(--kida-scribble-color);
  stroke-width: var(--kida-scribble-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

[data-kida-scribble][data-state="active"] path,
[data-kida-scribble][data-state="settled"] path {
  animation: kida-scribble-draw var(--kida-scribble-duration) var(--kida-ease-out) forwards;
}

@keyframes kida-scribble-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-kida-scribble][data-state] path {
    animation: none;
    stroke-dashoffset: 0;
  }
}

/*
 * Kida UI — motion tokens.
 * Plain CSS custom properties (ADR D7). No preprocessor, no Tailwind, no build step.
 */

:root {
  /* Durations */
  --kida-duration-xs: 100ms;
  --kida-duration-sm: 150ms;
  --kida-duration-md: 300ms;
  --kida-duration-lg: 500ms;
  --kida-duration-xl: 800ms;

  /* Easings */
  --kida-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --kida-ease-in: cubic-bezier(0.7, 0, 0.84, 0);
  --kida-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --kida-ease-spring: linear(0, 0.5, 0.9, 1.02, 1);

  /* Travel distances used by the enter/exit keyframes */
  --kida-distance-sm: 4px;
  --kida-distance-md: 8px;
  --kida-distance-lg: 16px;

  /* Stagger step between siblings */
  --kida-stagger: 60ms;
}

/*
 * The shared reduced-motion guard for CSS-driven animation in the library.
 * Durations collapse to ~0 by default. Components whose presence lifecycle cannot safely observe
 * a 1ms animation, such as Collapse, disable it explicitly and complete presence in their adapter.
 */
@media (prefers-reduced-motion: reduce) {
  :root {
    --kida-duration-xs: 1ms;
    --kida-duration-sm: 1ms;
    --kida-duration-md: 1ms;
    --kida-duration-lg: 1ms;
    --kida-duration-xl: 1ms;
    --kida-distance-sm: 0px;
    --kida-distance-md: 0px;
    --kida-distance-lg: 0px;
    --kida-stagger: 0ms;
  }
}

import { inView } from 'motion'
import { prefersReducedMotion } from './reduced-motion.motion.js'

export interface DrawInViewOptions {
  /** Animate only on the first viewport entry. @default true */
  once?: boolean
  /** How much of the element must be visible. @default 0.4 */
  amount?: 'some' | 'all' | number
}

export function drawInView(element: HTMLElement, options: DrawInViewOptions = {}): () => void {
  if (prefersReducedMotion()) {
    element.dataset.state = 'settled'
    return () => {}
  }

  const { once = true, amount = 0.4 } = options
  element.dataset.state = 'idle'

  const stop = inView(
    element,
    () => {
      element.dataset.state = 'active'
      if (once) stop()
      return once
        ? undefined
        : () => {
            element.dataset.state = 'idle'
          }
    },
    { amount },
  )

  return stop
}

const QUERY = '(prefers-reduced-motion: reduce)'

/**
 * Whether the user has asked for reduced motion.
 *
 * SSR-safe: returns `false` when there is no `window`, matching the CSS default
 * (the `prefers-reduced-motion` media query in `@kida-ui/styles` is the real guard;
 * this is for the JS-driven paths that CSS cannot express).
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false
  return window.matchMedia(QUERY).matches
}

/**
 * Subscribe to changes of the reduced-motion preference.
 * Returns an unsubscribe function. No-op (and immediately unsubscribable) on the server.
 */
export function watchReducedMotion(onChange: (reduced: boolean) => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return () => {}

  const list = window.matchMedia(QUERY)
  const handler = (event: MediaQueryListEvent) => onChange(event.matches)
  list.addEventListener('change', handler)
  return () => list.removeEventListener('change', handler)
}
